import{_ as a,c as i,o as t,a6 as o}from"./chunks/framework.BY05barL.js";const s="/ucasal-ssoo-estudio/assets/8-multiprogramacion.7J7aRbRu.png",h=JSON.parse('{"title":"Tiempo Compartido","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/tiempo-compartido.md","filePath":"unidad1/tiempo-compartido.md"}'),r={name:"unidad1/tiempo-compartido.md"};function n(l,e,d,p,c,m){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="tiempo-compartido" tabindex="-1">Tiempo Compartido <a class="header-anchor" href="#tiempo-compartido" aria-label="Permalink to &quot;Tiempo Compartido&quot;">​</a></h1><p>El tiempo compartido (time sharing) es una técnica fundamental en los sistemas operativos modernos que permite que múltiples usuarios utilicen una computadora de forma simultánea.</p><h2 id="caracteristicas-principales" tabindex="-1">Características principales <a class="header-anchor" href="#caracteristicas-principales" aria-label="Permalink to &quot;Características principales&quot;">​</a></h2><ul><li>Ejecución de múltiples procesos al mismo tiempo</li><li>Cada proceso se ejecuta en un intervalo de tiempo</li><li>El intervalo de tiempo se llama quantum (en milisegundos)</li><li>Permite la interactividad con múltiples usuarios</li></ul><p><img src="'+s+'" alt="Tiempo compartido"></p><h2 id="funcionamiento" tabindex="-1">Funcionamiento <a class="header-anchor" href="#funcionamiento" aria-label="Permalink to &quot;Funcionamiento&quot;">​</a></h2><p>El sistema de tiempo compartido funciona dividiendo el tiempo de CPU en pequeños intervalos (quantum) y asignando estos intervalos a diferentes procesos de forma rotativa:</p><ol><li>El sistema operativo asigna un quantum de tiempo a un proceso</li><li>Cuando el quantum termina o el proceso se bloquea, el sistema operativo cambia a otro proceso</li><li>Este cambio de contexto ocurre tan rápidamente que los usuarios tienen la impresión de que todos los programas se ejecutan simultáneamente</li></ol><h2 id="diferencias-con-el-procesamiento-por-lotes" tabindex="-1">Diferencias con el procesamiento por lotes <a class="header-anchor" href="#diferencias-con-el-procesamiento-por-lotes" aria-label="Permalink to &quot;Diferencias con el procesamiento por lotes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiempo Compartido</th><th>Procesamiento por Lotes</th></tr></thead><tbody><tr><td>Interactivo</td><td>No interactivo</td></tr><tr><td>Tiempo de respuesta rápido</td><td>Tiempo de respuesta lento</td></tr><tr><td>Optimizado para uso interactivo</td><td>Optimizado para uso eficiente de la CPU</td></tr><tr><td>Múltiples usuarios simultáneos</td><td>Procesamiento secuencial</td></tr></tbody></table><h2 id="ventajas" tabindex="-1">Ventajas <a class="header-anchor" href="#ventajas" aria-label="Permalink to &quot;Ventajas&quot;">​</a></h2><ul><li>Permite que múltiples usuarios trabajen simultáneamente</li><li>Mejora la utilización de recursos del sistema</li><li>Proporciona tiempos de respuesta rápidos</li><li>Facilita la colaboración entre usuarios</li></ul><h2 id="aplicaciones" tabindex="-1">Aplicaciones <a class="header-anchor" href="#aplicaciones" aria-label="Permalink to &quot;Aplicaciones&quot;">​</a></h2><p>El tiempo compartido es la base de los sistemas operativos multiusuario y multitarea que utilizamos hoy en día, desde servidores hasta computadoras personales y dispositivos móviles.</p>',14)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
